insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('55161aa1-c9f6-4e54-8fef-fe92f26bfbf8', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', $$inleiding: EAC richt dochteronderneming AnyWay op onder holding CAS$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-context1.png$$,
   $$European Air Company (EAC) is een luchtvaartmaatschappij die vluchten verzorgt in Europa. De laatste jaren ondervindt EAC toenemende concurrentie van luchtvaartmaatschappijen die sterk op de prijs concurreren door middel van budgetvluchten. Deze maatschappijen kunnen goedkoop vliegen omdat ze lagere loon- en overige vluchtkosten hebben. De directie van EAC onderzoekt in 2017 het plan om zelf een dochteronderneming op te richten, AnyWay, die ook tegen lage prijzen vluchten gaat aanbieden. De onderneming gaat dan verder onder de naam Combined Air Services (CAS). EAC en AnyWay worden eigendom van CAS (zie figuur 1). De huidige aandeelhouders van EAC zullen in dit plan hun aandelen omruilen in aandelen CAS. Daarnaast zal CAS extra aandelen uitgeven.$$, 'inline'),
  ('d67005c8-7a8a-4655-aa9c-ee367ed8fb60', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', $$figuur 1: organogram van de voorgestelde bedrijfsstructuur$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-context2.png$$,
   $$Figuur 1 organogram van de voorgestelde bedrijfsstructuur
Combined Air Services (CAS) met daaronder EAC en AnyWay.$$, 'inline'),
  ('82e981a0-dc74-4c78-9b98-7e4209a73342', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', $$voorwaarde aandeelhouders: piloten 20% van werktijd voor AnyWay tegen 10% minder loon$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-context3.png$$,
   $$De aandeelhouders staan positief tegenover het hierboven omschreven plan, op voorwaarde dat de piloten die nu nog werken op vluchten van EAC, bereid zijn 20% van hun werktijd te werken op vluchten van AnyWay, waarvoor ze 10% minder loon ontvangen.$$, 'inline'),
  ('a3be5b8f-5c6d-4b80-928c-75f7920ba966', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', $$overleg met twee vakbonden; afzet EAC met meer dan 20% gedaald$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-context4.png$$,
   $$Er bestaan twee vakbonden voor piloten. De directie van EAC nodigt deze uit voor overleg over het plan. De directie geeft aan dat het bedrijf er niet goed voor staat: “De laatste vier jaar is de afzet met meer dan 20% gedaald. Als er niets wordt gedaan, is de kans groot dat EAC op termijn failliet gaat.” De vakbonden willen een faillissement voorkomen. De directie onderbouwt haar uitspraken met gegevens uit tabel 1.$$, 'inline'),
  ('e47342b0-98f8-4651-8e4a-12e774095db0', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', $$tabel 1: marktontwikkeling vluchten in Europa, 2012-2016$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-context5.png$$,
   $$Tabel 1 marktontwikkeling vluchten in Europa, 2012 − 2016
| 2012 | 2013 | 2014 | 2015 | 2016
marktaandeel
standaardvluchten | 75% | 70% | 68% | 62% | 59%
waarvan vluchten EAC | 10,0%* | 10,4% | 10,3% | 9,0% | 8,9%
budgetvluchten | 25% | 30% | 32% | 38% | 41%
jaarlijkse groei alle vluchten (% t.o.v. het voorgaande jaar) | 2,75% | 3,33% | 3,87% | 1,86% | 3,05%
*Toelichting: 10% van alle standaardvluchten wordt uitgevoerd door EAC.$$, 'inline'),
  ('48056dd1-fba7-4e9e-bf8f-189f648e98c5', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', $$AnyWay gebruikt voorzieningen van EAC$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-context6.png$$,
   $$AnyWay zal gebruik gaan maken van alle voorzieningen van EAC, zoals hangars, incheckbalies en reparatiecentra. De directie stelt dat daardoor de gemiddelde winst per vlucht van EAC omhoog kan gaan.$$, 'inline'),
  ('94cf5c85-86ba-4e93-b52d-78bde8168d8f', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', $$vakbondsvoorstel: loonsverhoging op EAC-vluchten, gemiddeld +1% voor CAS$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-context7.png$$,
   $$Eén van de vakbonden zou akkoord willen gaan met 10% minder loon voor vluchten van AnyWay, vergeleken met het huidige loon bij EAC, als daar een zodanige loonsverhoging voor vluchten van EAC tegenover staat, dat de gemiddelde loonsverhoging voor CAS uitkomt op 1% ten opzichte van de huidige situatie. Daarbij is ervan uitgegaan dat de piloten daadwerkelijk 20% van hun werktijd vliegen voor AnyWay.$$, 'inline'),
  ('46029e3e-1175-424a-b34e-060eccee1ed8', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', $$directie: te grote loonsverhoging brengt aandelenuitgifte in gevaar$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-context8.png$$,
   $$De directie reageert: “Een te grote loonsverhoging brengt de opstart van de nieuwe bedrijfsstructuur in gevaar. De uitgifte van extra aandelen heeft alleen kans van slagen bij voldoende interesse van de kant van beleggers.”$$, 'inline'),
  ('fb6f0d59-f002-43bf-8c7d-63691b83ea7f', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', $$voorstel directie met voorwaarden voor beide vakbonden$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-context9.png$$,
   $$De directie stelt voor om alle EAC-piloten een nieuw contract aan te bieden bij CAS, waarbij ze 20% van de uren voor AnyWay vliegen voor 10% lager loon. Om dit voorstel aan te scherpen stelt de directie de volgende voorwaarden:
− Het voorstel geldt alleen bij een akkoord van beide vakbonden.
− Als één van de vakbonden niet akkoord gaat, zullen de daarbij aangesloten piloten een contract krijgen waarbij ze 30% bij AnyWay vliegen en de piloten van de vakbond die wel akkoord is, een contract waarbij ze maximaal 10% bij AnyWay vliegen. In beide gevallen ontvangen ze voor hun vluchten bij AnyWay 10% minder loon.
− Als beide vakbonden niet akkoord gaan, is het plan van de baan en dreigt er een faillissement van EAC. De directie weet dat alle piloten zijn aangesloten bij één van de twee vakbonden en dat beide vakbonden ongeveer even groot zijn. De vakbonden en de directie kunnen samen tot afspraken komen en zijn niet gebonden aan een cao. De vakbonden besluiten onafhankelijk van elkaar.$$, 'inline'),
  ('82d2c61b-d635-482b-a8ee-56fe9a1c605d', '4da09580-20b7-49ff-8472-aa984e9dfb58', $$inleiding: concessie voor elektrische bussen voor vijf jaar$$,
   $$economie-vwo-2021-i-groene-bussen-context1.png$$,
   $$In een grote stad wil het gemeentebestuur dat dieselbussen vervangen worden door elektrische bussen. Op die manier kan de milieudruk in de binnenstad worden verlaagd. Er ligt een voorstel op tafel om één van de bestaande busondernemingen een concessie (vergunning met uitsluiting van andere ondernemingen) te verlenen voor een periode van vijf jaar om met elektrische bussen te gaan rijden. Busondernemingen geven aan dat met het oog op het verschil in kosten tussen een elektrische bus en een dieselbus deze concessieperiode niet lang genoeg is.$$, 'inline'),
  ('78e82841-d40a-47ab-8b89-d594916a2a3e', '4da09580-20b7-49ff-8472-aa984e9dfb58', $$aanschafprijs en variabele kosten van elektrische en dieselbussen$$,
   $$economie-vwo-2021-i-groene-bussen-context2.png$$,
   $$De variabele kosten per kilometer zijn voor een elektrische bus weliswaar lager dan voor een dieselbus, maar de aanschafprijs van een elektrische bus (€ 500.000) is veel hoger dan van een dieselbus (€ 340.000). De aanschafprijs wordt hier gezien als constante kosten. Er wordt afgezien van de mogelijkheid om de bussen na de concessieperiode door te verkopen. Naar verwachting wordt er 60.000 kilometer per jaar per bus gereden. Figuur 1 laat het verloop van de kosten van beide typen bussen zien.$$, 'inline'),
  ('5dfb0127-e95a-46c0-afde-b3f32cc11e23', '4da09580-20b7-49ff-8472-aa984e9dfb58', $$figuur 1: aanschaf- en variabele kosten van elektrische en dieselbussen$$,
   $$economie-vwo-2021-i-groene-bussen-context3.png$$,
   $$Figuur 1 aanschaf- en variabele kosten van elektrische en dieselbussen
Grafiek van de kosten per bus in euro''s (0 tot 900.000) tegen het aantal gereden kilometers per bus (0 tot 550.000). Elektrisch (stippellijn) begint bij € 500.000, diesel (doorgetrokken lijn) begint bij € 340.000 en stijgt steiler; de lijnen snijden elkaar rond 400.000 km.$$, 'inline'),
  ('eb786701-6b8e-44af-917e-38a95ecf4aaa', '4da09580-20b7-49ff-8472-aa984e9dfb58', $$concessie met subsidie; wethouder: maatschappelijk voordeel$$,
   $$economie-vwo-2021-i-groene-bussen-context4.png$$,
   $$De gemeente kiest voor het verlenen van een concessie voor een periode van vijf jaar, wetende dat daarbij een jaarlijks subsidiebedrag nodig zal zijn. Busondernemingen kunnen een bod doen, waarin zij aangeven welk subsidiebedrag zij nodig hebben om het busvervoer rendabel te kunnen verzorgen. De gemeente zal de concessie toekennen aan de busonderneming die de minste subsidie nodig heeft. De wethouder van milieu beweert dat er ondanks de extra uitgaven aan subsidies voor de gemeente per saldo een maatschappelijk voordeel kan ontstaan.$$, 'inline'),
  ('26814b3a-14a1-4d33-8aad-5e6bf31e4c96', '4da09580-20b7-49ff-8472-aa984e9dfb58', $$tijdelijk wettelijk monopolie; voorwaarden i t/m v van de concessie$$,
   $$economie-vwo-2021-i-groene-bussen-context5.png$$,
   $$Door het toekennen van een concessie ontstaat er een tijdelijk wettelijk monopolie. Voor de concessie stelt de gemeente daarbij de volgende voorwaarden: i. 98% van de ritten van inwoners van de gemeente naar het centrum mag niet langer dan veertig minuten duren. ii. Maximaal 6% van de busritten mag vertraging hebben. iii. Alleen bij overmacht, zoals defecte bussen of stroomstoringen, mogen alsnog dieselbussen ingezet worden. iv. Alle bussen moeten voorzien zijn van een gps-trackingsysteem, waardoor een controlebureau van de gemeente te allen tijde de posities van de gebruikte bussen kan aflezen. v. Aan reizigers mag een prijs van maximaal € 0,11 per kilometer worden berekend.$$, 'inline'),
  ('fc9b214e-f288-4990-bd82-210c31e8ed34', 'b23907e0-f711-4d16-87ac-d389ec8fe8eb', $$inleiding: bedrijfspensioen met keuze tussen twee vormen van premiebetaling$$,
   $$economie-vwo-2021-i-op-weg-naar-het-pensioen-context1.png$$,
   $$In een land wil een technisch bedrijf een vestiging openen met uitsluitend recent afgestudeerde werknemers die geschoold zijn in de nieuwste technieken. Het bedrijf wilt haar werknemers een bedrijfspensioen aanbieden en besteedt het opzetten van het bedrijfspensioen uit aan een pensioenfonds. De nieuwe medewerkers krijgen een keuze tussen twee vormen van premiebetaling zoals weergegeven in figuur 1.$$, 'inline'),
  ('2cf893cd-dd70-4572-a828-addde73d3931', 'b23907e0-f711-4d16-87ac-d389ec8fe8eb', $$figuur 1: leeftijdsafhankelijke premie vergeleken met doorsneepremie$$,
   $$economie-vwo-2021-i-op-weg-naar-het-pensioen-context2.png$$,
   $$Figuur 1 leeftijdsafhankelijke premie vergeleken met doorsneepremie
Grafiek van de premie als percentage van het brutoloon tegen de leeftijd (25 tot 70, pensioenleeftijd 70). De doorsneepremie is een horizontale lijn op 18%; de leeftijdsafhankelijke premie stijgt van 8% op 25-jarige leeftijd tot ongeveer 29% op 70-jarige leeftijd.$$, 'inline'),
  ('d8969d92-2536-4aa1-a020-e8c04c9b3105', 'b23907e0-f711-4d16-87ac-d389ec8fe8eb', $$doorsneepremie en leeftijdsafhankelijke premie; uitkering 70% van gemiddeld brutoloon$$,
   $$economie-vwo-2021-i-op-weg-naar-het-pensioen-context3.png$$,
   $$De keuze tussen de twee vormen van premiebetaling is als volgt:
1 Doorsneepremie: jongere en oudere werknemers betalen hetzelfde vaste percentage van het brutoloon als pensioenpremie.
2 Leeftijdsafhankelijke premie: jongere werknemers betalen een lager percentage van het brutoloon als pensioenpremie dan ouderen. Naarmate ze ouder worden zullen ze een steeds groter gedeelte van hun brutoloon betalen aan pensioenpremie. Bij beide vormen van premiebetaling worden de premies gebruikt om vanaf de pensioenleeftijd een levenslange uitkering te garanderen die gelijk is aan 70% van het gemiddelde brutoloon. Er wordt uitgegaan van een gelijkblijvende pensioenleeftijd en lonen die geïndexeerd worden aan de inflatie.$$, 'inline'),
  ('636821bc-51b0-4698-bcde-b43582fddc6d', 'b23907e0-f711-4d16-87ac-d389ec8fe8eb', $$beleggingsbeleid: eerst aandelen, daarna staatsobligaties$$,
   $$economie-vwo-2021-i-op-weg-naar-het-pensioen-context4.png$$,
   $$Het pensioenfonds belegt het grootste deel van de ontvangen premies de eerste twintig jaar in aandelen. Daarna zal het grootste deel vooral in staatsobligaties worden belegd. Financieel directeur Hajar beargumenteert dat deze keuze, over de hele beleggingsperiode, zorgt voor een relatief hoog rendement in combinatie met een laag risico.$$, 'inline'),
  ('db28cdb1-caec-4b83-a835-aac9c9d4daa0', 'b23907e0-f711-4d16-87ac-d389ec8fe8eb', $$zorg over koopkracht op oudere leeftijd bij leeftijdsafhankelijke premie$$,
   $$economie-vwo-2021-i-op-weg-naar-het-pensioen-context5.png$$,
   $$De werknemers die kiezen voor een leeftijdsafhankelijke premie, zijn bezorgd over hun koopkracht op oudere leeftijd. Hoewel lonen geïndexeerd worden aan de inflatie, verwacht het bedrijf uitstekende doorgroeimogelijkheden te kunnen bieden. Financieel directeur Hajar stelt dat, gezien de verwachte gunstige carrièreontwikkeling binnen het bedrijf, de koopkracht van hun loon niet nadelig wordt beïnvloed ten opzichte van hun loon in hun jongere jaren.$$, 'inline'),
  ('9058b281-e616-46a6-bfea-3b9dd6931d7f', 'b23907e0-f711-4d16-87ac-d389ec8fe8eb', $$kanttekening: lage rente kan pensioenpremies verhogen$$,
   $$economie-vwo-2021-i-op-weg-naar-het-pensioen-context6.png$$,
   $$Financieel directeur Hajar dient het plan voor de twee vormen van premiebetaling in bij de directie. Zij maakt daarbij een kanttekening. Zij verwacht dat de premies in de toekomst hoger kunnen uitvallen dan weergegeven in figuur 1. Zij wijst daarbij op de mogelijke ontwikkelingen op de vermogensmarkt. Als de rente op de vermogensmarkt daalt, dan kunnen de pensioenpremies in de toekomst verder worden verhoogd.$$, 'inline'),
  ('79465ffe-8659-44cb-a1aa-3f34e39e04b8', '432086ca-70e7-485a-8300-fc6c1dbc34da', $$inleiding: verfbedrijven IC en Farbo; Farbo vraagt 12 euro per liter$$,
   $$economie-vwo-2021-i-prijsbeleid-in-de-verf-gezet-context1.png$$,
   $$Het verfbedrijf International Colors (IC) produceert een verfsoort voor roestend metaal. De directie bespreekt tijdens een vergadering de strategische keuzes die het bedrijf heeft om de winstgevendheid van de productie van deze specifieke verfsoort te verhogen. IC heeft op deze markt alleen concurrentie van Farbo die een vergelijkbare verfsoort op de markt brengt. Farbo streeft net als IC naar maximale totale winst en hanteert een prijs van 12 euro per liter verf.$$, 'inline'),
  ('4d683cc3-55a5-4418-bd08-6ecb884b16f4', '432086ca-70e7-485a-8300-fc6c1dbc34da', $$prijsafzetfunctie van IC$$,
   $$economie-vwo-2021-i-prijsbeleid-in-de-verf-gezet-context2.png$$,
   $$De prijsafzetfunctie van IC luidt als volgt:
qic = −2 pic + 2 pfb + 4
qic = hoeveelheid verkochte liters verf (× 100.000)
pic = prijs van IC verf per liter in euro’s
pfb = prijs van Farbo verf per liter in euro’s$$, 'inline'),
  ('a4be1d9c-9bca-41e2-be2a-43ecb1ac4550', '432086ca-70e7-485a-8300-fc6c1dbc34da', $$marginale kosten van IC: 8 euro$$,
   $$economie-vwo-2021-i-prijsbeleid-in-de-verf-gezet-context3.png$$,
   $$Verder geldt voor IC: MK (marginale kosten) = 8 euro$$, 'inline'),
  ('ab3e18ff-d961-4873-a350-dbcd463d8e73', '432086ca-70e7-485a-8300-fc6c1dbc34da', $$prijsbeleid: prijs gelijk, 10% hoger of 10% lager$$,
   $$economie-vwo-2021-i-prijsbeleid-in-de-verf-gezet-context4.png$$,
   $$De directie van IC bespreekt gedurende de vergadering het prijsbeleid en overweegt daarbij drie mogelijkheden: de prijs gelijk laten, verhogen met 10% of verlagen met 10%. De directie verwacht dat Farbo op dezelfde manier zal reageren op het prijsbeleid van IC. Een directielid geeft de situatie weer met onderstaande spelboom.$$, 'inline'),
  ('1e178ced-79f9-481c-85a7-e62d3dc585ff', '432086ca-70e7-485a-8300-fc6c1dbc34da', $$figuur 1: spelboom met prijsstrategieën en totale winst$$,
   $$economie-vwo-2021-i-prijsbeleid-in-de-verf-gezet-context5.png$$,
   $$Figuur 1 spelboom
Spelboom: prijsstrategieën en totale winst (× € 100.000). IC kiest eerst een prijs, daarna Farbo (winst IC; winst Farbo):
IC € 12,10 → Farbo € 13,20: 15,4; 25,6 | € 12,00: 5,6; 27,0 | € 10,80: −4,3; 22,6
IC € 11,00 → Farbo € 13,20: 15,2; 11,3 | € 12,00: 8,0; 16,0 | € 10,80: 0,8; 14,9
IC € 9,90 → Farbo € 13,20: 10,1; −2,9 | € 12,00: 5,6; 5,0 | € 10,80: 1,0; 7,2$$, 'inline'),
  ('4731c5b6-777f-49da-b3c3-e4f9b0cc5616', '432086ca-70e7-485a-8300-fc6c1dbc34da', $$analist Havermans: simultaan spel met twee Nash-evenwichten$$,
   $$economie-vwo-2021-i-prijsbeleid-in-de-verf-gezet-context6.png$$,
   $$Analist Havermans onderzoekt wat er gebeurt als beide bedrijven tegelijkertijd moeten beslissen. Deze situatie kan worden geanalyseerd met matrix 1, die de verwachte totale winst (x € 100.000) toont bij iedere combinatie van prijszettingen per liter verf. Zij signaleert daarin twee Nash-evenwichten.$$, 'inline'),
  ('fd0e462d-74d2-4439-84c4-c68a0f00a86c', '432086ca-70e7-485a-8300-fc6c1dbc34da', $$matrix 1: simultaan spel bij prijszettingen van IC en Farbo$$,
   $$economie-vwo-2021-i-prijsbeleid-in-de-verf-gezet-context7.png$$,
   $$Matrix 1 simultaan spel bij prijszettingen van IC en Farbo
IC (rijen) / Farbo (kolommen), prijs per liter | € 13,20 | € 12,00 | € 10,80
€ 12,10 | 15,4; 25,6 | 5,6; 27,0 | − 4,3; 22,6
€ 11,00 | 15,2; 11,3 | 8,0; 16,0 | 0,8; 14,9
€ 9,90 | 10,1; −2,9 | 5,6; 5,0 | 1,0; 7,2$$, 'inline'),
  ('f51ca9f5-d4f6-4448-b7d3-0f0de4eefcb6', '432086ca-70e7-485a-8300-fc6c1dbc34da', $$marketingcampagne met drie gewenste effecten$$,
   $$economie-vwo-2021-i-prijsbeleid-in-de-verf-gezet-context8.png$$,
   $$Havermans stelt: “Bij onveranderd prijsbeleid kan IC zich meer richten op een marketingcampagne met nadruk op de goede reputatie van de verfsoort die IC sinds zijn oprichting verkoopt. De campagne moet gericht zijn op zowel klantenbinding als op het aantrekken van klanten van Farbo en van nieuwe kopers van deze verfsoort. Als gevolg van de campagne zou de prijsafzetfunctie van IC veranderen, onder de veronderstelling dat Farbo niet ook een marketingcampagne gaat voeren.” Slechts één van de volgende vier prijsafzetfuncties combineert alle drie de gewenste effecten.$$, 'inline'),
  ('2b929e7e-ec72-43f4-99df-8691ea4d8e9b', '432086ca-70e7-485a-8300-fc6c1dbc34da', $$vier prijsafzetfuncties a t/m d$$,
   $$economie-vwo-2021-i-prijsbeleid-in-de-verf-gezet-context9.png$$,
   $$a qic = −1,5 pic + 2,0 pfb + 3
b qic = −2,5 pic + 2,0 pfb + 4
c qic = −1,5 pic + 2,5 pfb + 5
d qic = −2,5 pic + 1,5 pfb + 6$$, 'inline'),
  ('7b7a588f-0baa-431b-93d4-297becf83171', '0ed720b3-9e3a-4830-956c-cde7657383c9', $$inleiding: Imareca wil devalueren met 20% tegenover de valuta van Nachi$$,
   $$economie-vwo-2021-i-devaluatie-van-de-wal-in-de-sloot-context1.png$$,
   $$In het land Imareca zijn presidentsverkiezingen. Centraal in de campagne staat het stimuleren van de zwakke economie. De werkloosheid neemt toe en de lopende rekening van de betalingsbalans met de belangrijkste handelspartner, het land Nachi, vertoont een groot tekort. De valuta van Imareca heeft een vaste wisselkoers ten opzichte van die van Nachi. Een kandidaat kondigt aan dat hij als president onmiddellijk over zal gaan tot een devaluatie van 20% ten opzichte van de valuta van Nachi. Dit zou volgens hem zowel het tekort op de lopende rekening van de betalingsbalans met Nachi als de binnenlandse werkloosheid verminderen.$$, 'inline'),
  ('91205475-3923-4f1a-86e8-a9112957b563', '0ed720b3-9e3a-4830-956c-cde7657383c9', $$econoom Paulus: devaluatie op korte termijn nadelig$$,
   $$economie-vwo-2021-i-devaluatie-van-de-wal-in-de-sloot-context2.png$$,
   $$Econoom Paulus stelt: “Devaluatie zal op korte termijn juist nadelig zijn voor de economie van Imareca. Dit heeft te maken met de prijselasticiteiten van de import en van de export. De importwaarde, gemeten in eigen valuta, kan op korte termijn stijgen waardoor het tekort op de lopende rekening met Nachi verder zal toenemen.” De formules van de prijselasticiteiten van de export en van de import van goederen en diensten luiden:$$, 'inline'),
  ('f47eb3f5-a57d-42de-9611-5722b4b65792', '0ed720b3-9e3a-4830-956c-cde7657383c9', $$formule prijselasticiteit van de export$$,
   $$economie-vwo-2021-i-devaluatie-van-de-wal-in-de-sloot-context3.png$$,
   $$prijselasticiteit van de export = % verandering exportvolume / % verandering exportprijs in vreemde valuta$$, 'inline'),
  ('c95a8943-5c12-46cf-9d6c-51ea27de4a3d', '0ed720b3-9e3a-4830-956c-cde7657383c9', $$formule prijselasticiteit van de import$$,
   $$economie-vwo-2021-i-devaluatie-van-de-wal-in-de-sloot-context4.png$$,
   $$prijselasticiteit van de import = % verandering importvolume / % verandering importprijs in eigen valuta$$, 'inline'),
  ('5908e58c-449a-4bcc-af8d-2a0bf16a14ee', '0ed720b3-9e3a-4830-956c-cde7657383c9', $$korte termijn: prijselasticiteit export −0,5 en import −0,4$$,
   $$economie-vwo-2021-i-devaluatie-van-de-wal-in-de-sloot-context5.png$$,
   $$Analyses wijzen uit dat op korte termijn de prijselasticiteit van de export -0,5 bedraagt en de prijselasticiteit van de import -0,4.$$, 'inline'),
  ('453adf88-ad88-47d5-aef0-dc207e1112b2', '0ed720b3-9e3a-4830-956c-cde7657383c9', $$toelichting noemers van beide formules$$,
   $$economie-vwo-2021-i-devaluatie-van-de-wal-in-de-sloot-context6.png$$,
   $$Beide formules zijn varianten op de prijselasticiteit van de vraag. Bij de prijselasticiteit van de export staat in de noemer de prijs in vreemde valuta, terwijl bij de prijselasticiteit van de import in de noemer de prijs is genoteerd in eigen (binnenlandse) valuta.$$, 'inline'),
  ('085508ec-38f6-46b1-bcd0-3244d44f13c7', '0ed720b3-9e3a-4830-956c-cde7657383c9', $$Paulus: import op langere termijn elastischer$$,
   $$economie-vwo-2021-i-devaluatie-van-de-wal-in-de-sloot-context7.png$$,
   $$Paulus stelt verder: “De import zal op langere termijn mogelijk elastischer zijn, waardoor er dan meer kans is dat het tekort op de lopende rekening van de betalingsbalans met Nachi zal verminderen.”$$, 'inline'),
  ('47c19a7f-764b-4b79-8b99-f39c83e1a7f9', '0ed720b3-9e3a-4830-956c-cde7657383c9', $$Paulus: devaluatie en binnenlands loonniveau$$,
   $$economie-vwo-2021-i-devaluatie-van-de-wal-in-de-sloot-context8.png$$,
   $$Paulus: “Op de lange termijn kan een devaluatie echter ook effect hebben op het binnenlandse loonniveau. Dit kan van invloed zijn op de lopende rekening van de betalingsbalans, wat de beoogde vermindering van de werkloosheid in de weg kan staan.”$$, 'inline'),
  ('ae463905-dd3b-4731-a4a8-892c00c94ee9', '0ed720b3-9e3a-4830-956c-cde7657383c9', $$econoom Liman: overheid laten bezuinigen$$,
   $$economie-vwo-2021-i-devaluatie-van-de-wal-in-de-sloot-context9.png$$,
   $$Econoom Liman stelt binnenlands beleid voor. “Als we gebruikmaken van het kringloopmodel, is te zien dat er in Imareca sprake is van een overheidstekort dat niet wordt opgevangen door een particulier spaaroverschot. Ik stel voor dat de overheid gaat bezuinigen om daarmee ook het tekort op de lopende rekening te verlagen.” Liman onderbouwt zijn visie met gegevens uit tabel 1.$$, 'inline'),
  ('3958d2e8-aadb-4a60-ae01-7aeed378fe6a', '0ed720b3-9e3a-4830-956c-cde7657383c9', $$tabel 1: macro-economische gegevens van Imareca in 2019$$,
   $$economie-vwo-2021-i-devaluatie-van-de-wal-in-de-sloot-context10.png$$,
   $$Tabel 1 macro-economische gegevens van Imareca in 2019
variabele | in procenten van het bbp
overheidstekort | 2,6
particuliere besparingen (S) | …
particuliere investeringen (I) | 20,3
tekort op de lopende rekening | 3,2$$, 'inline'),
  ('86e5b2c0-3b6b-4460-bd51-afbe32ce10fe', '0ed720b3-9e3a-4830-956c-cde7657383c9', $$presidentskandidaat wijst voorstel Liman af$$,
   $$economie-vwo-2021-i-devaluatie-van-de-wal-in-de-sloot-context11.png$$,
   $$De presidentskandidaat wil zijn plannen doorzetten: “Ook al vermindert het tekort op de lopende rekening niet van vandaag op morgen, er is op termijn tenminste uitzicht op verbetering. Het voorstel van Liman ga ik niet uitvoeren. Hierdoor zou de werkloosheid al te zeer toenemen.”$$, 'inline'),
  ('9947378b-25e5-43cf-ae2a-71b5f5ea8bff', '220a94cb-2fa9-4990-be33-d873f3f757a7', $$inleiding: econoom Pikets onderzoekt inkomensverschillen in Alpha$$,
   $$economie-vwo-2021-i-gelijkheid-en-groei-context1.png$$,
   $$Econoom Pikets onderzoekt primaire en secundaire inkomensverschillen, maar ook de inkomensontwikkeling in het land Alpha. In zijn onderzoek zijn alle geldbedragen genoteerd in de valuta van Alpha, de Alphaanse dollar (A$). Tabel 1 schetst de primaire inkomensverdeling in 2016.$$, 'inline'),
  ('80af6fe9-cf62-4ce2-adda-c8c7ab7c8f75', '220a94cb-2fa9-4990-be33-d873f3f757a7', $$tabel 1: primaire inkomensverdeling in land Alpha in 2016$$,
   $$economie-vwo-2021-i-gelijkheid-en-groei-context2.png$$,
   $$Tabel 1 primaire inkomensverdeling in land Alpha in 2016
inkomensklasse | aantal personen | gemiddeld primair jaarinkomen in A$ per persoon
1 | 3 mln. | 2.500
2 | 2 mln. | 7.500
3 | 1 mln. | 15.000
4 | 0,75 mln. | 30.000
5 | 0,25 mln. | 50.000$$, 'inline'),
  ('f8218243-ea89-469a-8844-bcec83e9612a', '220a94cb-2fa9-4990-be33-d873f3f757a7', $$inkomstenbelasting 30%, heffingskorting A$ 250, bijstand A$ 1.200$$,
   $$economie-vwo-2021-i-gelijkheid-en-groei-context3.png$$,
   $$Voor de inkomstenbelasting geldt één algemeen tarief van 30% voor primaire jaarinkomens en één algemene heffingskorting van A$ 250 per belastingplichtige. Mensen zonder enig primair inkomen kunnen in dit land aanspraak maken op een bijstandsuitkering van A$ 1.200 per jaar. De bijstandsuitkering is belastingvrij. De financiering loopt via de begroting van de overheid. Als maatstaf voor inkomensongelijkheid gebruikt Pikets de Ginicoëfficiënt.$$, 'inline'),
  ('1f7344dd-f963-4d21-b14c-db90d8d5e95f', '220a94cb-2fa9-4990-be33-d873f3f757a7', $$Pikets: bijstandswet kan ongewenste effecten hebben$$,
   $$economie-vwo-2021-i-gelijkheid-en-groei-context4.png$$,
   $$Pikets meent dat de bijstandswet ongewenste effecten kan hebben: “Sommige mensen met inkomen uit arbeid of vermogen zijn nu door de werking van het belastingstelsel slechter af dan mensen met een bijstandsuitkering.”$$, 'inline'),
  ('6917d05d-195a-4c48-917f-bf6a58f4bd73', '220a94cb-2fa9-4990-be33-d873f3f757a7', $$leerplicht en scholing sinds 1990$$,
   $$economie-vwo-2021-i-gelijkheid-en-groei-context5.png$$,
   $$In de jaren 1980-1990 behoorde Alpha tot de groep landen met de laagste inkomens ter wereld. De overheid van Alpha heeft daarom in 1990 besloten om een leerplicht in te voeren en scholing financieel te ondersteunen. Deze investeringen hebben geleid tot een toename van de economische groei.$$, 'inline'),
  ('b5af6e5f-f148-4811-9b0c-e456496dbd43', '220a94cb-2fa9-4990-be33-d873f3f757a7', $$vrij kapitaalverkeer; wisselkoers veranderd en saldo lopende rekening gestegen$$,
   $$economie-vwo-2021-i-gelijkheid-en-groei-context6.png$$,
   $$Daarnaast is het kapitaalverkeer sinds 2010 veel vrijer geworden, waardoor de wisselkoers van de Alphaanse valuta ten opzichte van de Amerikaanse dollar aanmerkelijk is veranderd. Pikets veronderstelt dat door de wisselkoersverandering het saldo lopende rekening is gestegen en hierdoor het nationaal inkomen in Alpha is gestegen.$$, 'inline'),
  ('6871024e-c474-4e74-bce7-d9c931cf3341', '220a94cb-2fa9-4990-be33-d873f3f757a7', $$stimulerend begrotingsbeleid: maatregelen i en ii$$,
   $$economie-vwo-2021-i-gelijkheid-en-groei-context7.png$$,
   $$Na jaren van economische groei voorziet de regering van Alpha in 2017 een neergang van de conjunctuur en wil stimulerend begrotingsbeleid voeren. Er worden twee maatregelen bediscussieerd: i. verlaging van het algemene tarief van de inkomstenbelasting, met afschaffing van de algemene heffingskorting en ii. gelijk houden van het algemene tarief van de inkomstenbelasting, met verhoging van de algemene heffingskorting.$$, 'inline'),
  ('b71824c8-986f-4004-ab49-529b30410ae0', '220a94cb-2fa9-4990-be33-d873f3f757a7', $$aanname Pikets: hoge inkomens sparen meer van een extra dollar$$,
   $$economie-vwo-2021-i-gelijkheid-en-groei-context8.png$$,
   $$Pikets gaat uit van de volgende aanname: mensen met een hoog inkomen sparen meer van een extra Alphaanse dollar netto-inkomen dan mensen met een laag inkomen.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('afb5609b-b976-437d-a732-35f124c2c7ff', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', 1,
   '[{"domain": "Markt", "subdomain": "Vraag en aanbod"}, {"domain": "Markt", "subdomain": "Marktstructuur"}]'::jsonb,
   '["marktaandeel", "afzet berekenen", "indexcijfers", "procentuele verandering berekenen", "marktgroei"]'::jsonb,
   $$Met marktaandelen en jaarlijkse marktgroei berekenen hoeveel de afzet van een onderneming is gedaald.$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-vraag1.png$$, $$2p 1 Toon met een berekening aan dat de afzet van EAC in 2016 ten opzichte van 2012 met meer dan 20% is gedaald.$$, array['55161aa1-c9f6-4e54-8fef-fe92f26bfbf8', 'd67005c8-7a8a-4655-aa9c-ee367ed8fb60', '82e981a0-dc74-4c78-9b98-7e4209a73342', 'a3be5b8f-5c6d-4b80-928c-75f7920ba966', 'e47342b0-98f8-4651-8e4a-12e774095db0']::uuid[]),
  ('8e90a8d6-c85d-419e-8ca7-a054777beb08', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', 2,
   '[{"domain": "Markt", "subdomain": "Vraag en aanbod"}]'::jsonb,
   '["vaste kosten", "gemiddelde kosten", "kostenspreiding", "gemiddelde winst", "schaalvoordelen"]'::jsonb,
   $$Verklaren hoe gedeeld gebruik van voorzieningen via lagere gemiddelde vaste kosten de winst per eenheid verhoogt.$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-vraag2.png$$, $$2p 2 Verklaar de stelling van de directie.$$, array['48056dd1-fba7-4e9e-bf8f-189f648e98c5']::uuid[]),
  ('6d71eb36-f96d-4906-8e41-4f101fa4b588', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', 3,
   '[{"domain": "Welvaart en groei", "subdomain": "Arbeidsmarkt en werkloosheid"}]'::jsonb,
   '["loonsverhoging berekenen", "gewogen gemiddelde", "loonkosten", "procentuele verandering berekenen"]'::jsonb,
   $$Met een gewogen gemiddelde berekenen hoeveel procent de lonen moeten stijgen bij een gegeven gemiddelde loonstijging.$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-vraag3.png$$, $$2p 3 Bereken hoeveel procent de lonen op vluchten van EAC dan moeten stijgen. Rond je antwoord af op twee decimalen.$$, array['82e981a0-dc74-4c78-9b98-7e4209a73342', '94cf5c85-86ba-4e93-b52d-78bde8168d8f']::uuid[]),
  ('cf4476cd-9dda-404e-b156-1cc90bd3465d', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', 4,
   '[{"domain": "Risico en Informatie", "subdomain": "Beleggen"}, {"domain": "Risico en Informatie", "subdomain": "Asymmetrische informatie in bedrijf"}]'::jsonb,
   '["aandelenuitgifte", "verwacht rendement", "winstverwachting", "dividend", "vermogen aantrekken"]'::jsonb,
   $$Uitleggen hoe hogere loonkosten via lagere winstverwachtingen een aandelenuitgifte minder aantrekkelijk maken.$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-vraag4.png$$, $$2p 4 Leg uit dat een te sterke loonsverhoging het succes van een aandelenuitgifte van CAS in gevaar kan brengen.$$, array['55161aa1-c9f6-4e54-8fef-fe92f26bfbf8', '46029e3e-1175-424a-b34e-060eccee1ed8']::uuid[]),
  ('6f454a5c-727b-4f83-b91d-cd9055db4833', '6fcd79db-4cea-4de8-9c57-9abd614aa6a1', 5,
   '[{"domain": "Samenwerken en onderhandelen", "subdomain": "Speltheorie"}]'::jsonb,
   '["pay-off matrix", "dominante strategie", "Nash-evenwicht", "gevangenendilemma", "simultaan spel"]'::jsonb,
   $$Met strategieën van twee vakbonden beredeneren of beide akkoord gaan met een voorstel.$$,
   $$economie-vwo-2021-i-anyway-van-de-grond-vraag5.png$$, $$2p 5 Zullen beide vakbonden, uitsluitend op basis van bovenstaand voorstel en de betreffende aanscherping van de directie, akkoord gaan? Licht je antwoord toe door strategieën van beide vakbonden te vergelijken.$$, array['a3be5b8f-5c6d-4b80-928c-75f7920ba966', 'fb6f0d59-f002-43bf-8c7d-63691b83ea7f']::uuid[]),
  ('e881768f-cf9d-408c-9ecd-18d9332be7f9', '4da09580-20b7-49ff-8472-aa984e9dfb58', 6,
   '[{"domain": "Markt", "subdomain": "Vraag en aanbod"}]'::jsonb,
   '["variabele kosten", "constante kosten", "kosten per kilometer berekenen", "grafiek aflezen"]'::jsonb,
   $$Uit een kostengrafiek berekenen hoeveel de variabele kosten per kilometer van twee alternatieven verschillen.$$,
   $$economie-vwo-2021-i-groene-bussen-vraag6.png$$, $$1p 6 Bereken hoeveel euro de variabele kosten per kilometer van het rijden met een elektrische bus lager zijn dan van het rijden met een dieselbus.$$, array['82d2c61b-d635-482b-a8ee-56fe9a1c605d', '78e82841-d40a-47ab-8b89-d594916a2a3e', '5dfb0127-e95a-46c0-afde-b3f32cc11e23']::uuid[]),
  ('70e51fe8-57ad-42dc-9df8-32550efed099', '4da09580-20b7-49ff-8472-aa984e9dfb58', 7,
   '[{"domain": "Markt", "subdomain": "Vraag en aanbod"}]'::jsonb,
   '["break-even", "vaste kosten", "variabele kosten", "kostenvergelijking", "terugverdientijd"]'::jsonb,
   $$Berekenen na hoeveel jaar een duurdere investering met lagere variabele kosten goedkoper wordt.$$,
   $$economie-vwo-2021-i-groene-bussen-vraag7.png$$, $$1p 7 Bepaal met een berekening hoelang de concessieperiode minimaal moet zijn voordat het rijden met elektrische bussen goedkoper is dan met dieselbussen.$$, array['78e82841-d40a-47ab-8b89-d594916a2a3e', '5dfb0127-e95a-46c0-afde-b3f32cc11e23']::uuid[]),
  ('4f087dff-96f1-4f31-b24d-bc1d471f3e55', '4da09580-20b7-49ff-8472-aa984e9dfb58', 8,
   '[{"domain": "Samenwerken en onderhandelen", "subdomain": "Suboptimale situaties"}, {"domain": "Markt", "subdomain": "Doelmatigheid en economische politiek"}]'::jsonb,
   '["negatief extern effect", "subsidie", "maatschappelijke welvaart", "milieu", "internaliseren"]'::jsonb,
   $$Uitleggen hoe subsidie voor schonere bussen via minder negatieve externe effecten maatschappelijk voordeel geeft.$$,
   $$economie-vwo-2021-i-groene-bussen-vraag8.png$$, $$2p 8 Leg de bewering van de wethouder uit.$$, array['82d2c61b-d635-482b-a8ee-56fe9a1c605d', 'eb786701-6b8e-44af-917e-38a95ecf4aaa']::uuid[]),
  ('fb331c48-0f5f-48f8-8d3c-d44cc82461bd', '4da09580-20b7-49ff-8472-aa984e9dfb58', 9,
   '[{"domain": "Risico en Informatie", "subdomain": "Asymmetrische informatie in bedrijf"}, {"domain": "Markt", "subdomain": "Marktstructuur"}]'::jsonb,
   '["principaal-agentprobleem", "informatieasymmetrie", "concessie", "wettelijk monopolie", "controle"]'::jsonb,
   $$Uitleggen welk principaal-agentprobleem bij een concessie optreedt en welke voorwaarden dit beperken.$$,
   $$economie-vwo-2021-i-groene-bussen-vraag9.png$$, $$4p 9 Leg uit dat een principaal-agentprobleem tussen de gemeente en de busonderneming kan optreden, en leg uit welke twee voorwaarden uit de overeenkomst dit probleem kunnen verminderen.$$, array['26814b3a-14a1-4d33-8aad-5e6bf31e4c96']::uuid[]),
  ('b63b968a-280a-402e-a374-2e10869b71e9', 'b23907e0-f711-4d16-87ac-d389ec8fe8eb', 10,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Intertemporele ruil"}, {"domain": "Ruilen over de tijd", "subdomain": "Registratie intertemporele ruil"}]'::jsonb,
   '["tijdsvoorkeur", "doorsneepremie", "leeftijdsafhankelijke premie", "pensioenpremie", "consumptie spreiden"]'::jsonb,
   $$Uitleggen welke premievorm een werknemer met een lage tijdsvoorkeur kiest.$$,
   $$economie-vwo-2021-i-op-weg-naar-het-pensioen-vraag10.png$$, $$2p 10 Leg uit voor welke premiebetaling een jonge werknemer zal kiezen met een relatief lage tijdsvoorkeur.$$, array['fc9b214e-f288-4990-bd82-210c31e8ed34', '2cf893cd-dd70-4572-a828-addde73d3931', 'd8969d92-2536-4aa1-a020-e8c04c9b3105']::uuid[]),
  ('8e731d34-200c-4607-a812-73714e8c35ad', 'b23907e0-f711-4d16-87ac-d389ec8fe8eb', 11,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Registratie intertemporele ruil"}]'::jsonb,
   '["levensverwachting", "doorsneepremie", "pensioenuitkering", "kapitaaldekkingsstelsel", "pensioenpremie"]'::jsonb,
   $$Uitleggen hoe een stijgende levensverwachting de doorsneepremie verhoogt.$$,
   $$economie-vwo-2021-i-op-weg-naar-het-pensioen-vraag11.png$$, $$2p 11 Leg uit hoe de lijn van de doorsneepremie zal verschuiven indien de levensverwachting in dit land stijgt.$$, array['2cf893cd-dd70-4572-a828-addde73d3931', 'd8969d92-2536-4aa1-a020-e8c04c9b3105']::uuid[]),
  ('50e699bd-080f-46ec-9986-d00428f3d0d6', 'b23907e0-f711-4d16-87ac-d389ec8fe8eb', 12,
   '[{"domain": "Risico en Informatie", "subdomain": "Beleggen"}]'::jsonb,
   '["aandelen", "obligaties", "risico en rendement", "beleggingshorizon", "spreiding in de tijd"]'::jsonb,
   $$Uitleggen waarom eerst beleggen in aandelen en later in obligaties hoog rendement met laag risico combineert.$$,
   $$economie-vwo-2021-i-op-weg-naar-het-pensioen-vraag12.png$$, $$3p 12 Leg de argumentatie van de financieel directeur uit.$$, array['636821bc-51b0-4698-bcde-b43582fddc6d']::uuid[]),
  ('a1f789bb-405d-43e1-bc61-4907fa747b50', 'b23907e0-f711-4d16-87ac-d389ec8fe8eb', 13,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Registratie intertemporele ruil"}, {"domain": "Goede tijden, slechte tijden", "subdomain": "Conjunctuur"}]'::jsonb,
   '["koopkracht", "leeftijdsafhankelijke premie", "loonindexatie", "inkomensontwikkeling", "pensioenpremie"]'::jsonb,
   $$Uitleggen waarom bij een stijgende leeftijdsafhankelijke premie de koopkracht door loonstijging behouden blijft.$$,
